use std::future::Future;
use tokio::task::{JoinError, JoinHandle};
struct Workers { handles: Vec<JoinHandle<u64>> }
impl Workers {
    fn spawn(&mut self, work: impl Future<Output = u64> + Send + 'static) {
        self.handles.push(tokio::spawn(work));
    }
    async fn next(&mut self) -> Option<Result<u64, JoinError>> {
        loop {
            if self.handles.is_empty() { return None; }
            if let Some(index) = self.handles.iter().position(JoinHandle::is_finished) {
                return Some(self.handles.swap_remove(index).await);
            }
            tokio::task::yield_now().await;
        }
    }
}
impl Drop for Workers { fn drop(&mut self) { for task in &self.handles { task.abort(); } } }
async fn run() -> Vec<Result<u64, JoinError>> {
    let mut workers = Workers { handles: Vec::new() };
    workers.spawn(async { 3 }); workers.spawn(async { 8 });
    let mut results = Vec::new();
    while let Some(result) = workers.next().await { results.push(result); }
    results
}

