use tokio_util::task::TaskTracker;
use tokio_util::sync::CancellationToken;
struct Service { stop: CancellationToken, tasks: TaskTracker }
impl Service {
    async fn finish(&self) {
        self.stop.cancel();
        self.tasks.close();
        loop {
            if self.tasks.is_empty() { break; }
            tokio::task::yield_now().await;
        }
    }
}

use tokio::sync::mpsc::Receiver;
use tokio_util::sync::CancellationToken;
async fn consume(mut input: Receiver<String>, stop: CancellationToken) -> Vec<String> {
    let mut received = Vec::new();
    loop {
        tokio::select! {
            biased;
            _ = stop.cancelled() => break,
            item = input.recv() => match item {
                Some(text) => received.push(text),
                None => break,
            }
        }
    }
    received
}

