use clap::{Arg, ArgAction, Command};
use std::ffi::OsString;
use std::path::PathBuf;
struct Args { output: Option<PathBuf>, verbose: bool }
fn parse(input: Vec<OsString>) -> Result<Args, clap::Error> {
    let mut matches = Command::new("export")
        .arg(Arg::new("output").long("output").value_parser(clap::value_parser!(PathBuf)))
        .arg(Arg::new("verbose").long("verbose").action(ArgAction::SetTrue))
        .try_get_matches_from(input)?;
    Ok(Args { output: matches.remove_one("output"), verbose: matches.get_flag("verbose") })
}

use clap::Command;
use std::ffi::OsString;
fn parse(plugins: &[String], input: Vec<OsString>) -> Result<String, clap::Error> {
    let mut command = Command::new("runner").subcommand_required(true);
    for name in plugins { command = command.subcommand(Command::new(name.clone())); }
    let matches = command.try_get_matches_from(input)?;
    Ok(matches.subcommand_name().expect("required by grammar").to_owned())
}

